input.sparql:
PREFIX bldg: <http://buildgraph.org/BG_large_office_2004_0000#>
PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?zone ?point ?ts ?purl WHERE {
  ?zone a brick:HVAC_Zone ; rdfs:label "Perimeter_bot_ZN_2" .
  ?zone brick:hasPoint ?point .
  ?point a brick:Occupancy_Sensor .
  OPTIONAL { ?point ref:hasExternalReference ?purl . }
}

